/* YSF modem simulation: our frame encoder (sync + FICH + DCH) -> C4FM
 * modulation at 8 kHz -> simulated FM channel -> our 8 kHz demodulator and
 * frame decoder.
 *
 * There are NO public, verifiable YSF test vectors (docs/ysf-c4fm.md): the
 * vectors here are generated by our own encoder from the spec, so this test
 * proves the demodulator and decoder against themselves -- not against real
 * air captures. The one external anchor is MMDVMHost: the whitening check
 * below compares our PN(9,5) generator byte by byte with MMDVM's fixed
 * WHITENING_DATA table, and the Golay spot checks compare against MMDVM's
 * ENCODING_TABLE_24128 values.
 *
 *   test_ysf_modem            assertions (CI) */
#include "ysf_frame.h"
#include "ysf_modem.h"
#include "ysf_channel.h"
#include <assert.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* Every simulated reception starts with the receiver idling on noise (100 ms), and the squelch opens at the
 * carrier start: YSF has no preamble, so a squelch delay would lose the whole first sync (20 symbols =
 * 4.17 ms). The demodulator reacquires exactly when the carrier appears. */
#define LEAD_S 0.1
enum { SQUELCH_MS = 0 };
#ifndef TXG
#define TXG 512   /* modulator output: 2 LSB per Hz, headroom for high-pass pre-compensation */
#endif
enum { MAX_FRAMES = 16, MAX_DIB = 16000, MAX_SAMP = 60000, TX_GAIN_Q8 = TXG };

static unsigned checks, failures;
#define CHECK(c) do { checks++; if (!(c)) { failures++; fprintf(stderr, "FAIL %s:%d: %s\n", __FILE__, __LINE__, #c); } } while (0)

static uint8_t txdib[MAX_DIB], rxdib[MAX_DIB];
static int16_t tx8[MAX_SAMP], rx8[MAX_SAMP];

/* MMDVMHost's WHITENING_DATA (YSFPayload.cpp): the fixed 20-byte table our
 * PN(9,5) generator must reproduce. */
static const uint8_t mmdvm_whitening[20] = {
    0x93, 0xD7, 0x51, 0x21, 0x9C, 0x2F, 0x6C, 0xD0, 0xEF, 0x0F,
    0xF8, 0x3D, 0xF1, 0x73, 0x20, 0x94, 0xED, 0x1E, 0x7C, 0xD8
};

/* Callsigns, 10 characters each, space padded (Yaesu Table 4-2). */
static const char dest_cs[10] = "CQ        ";
static const char src_cs[10] = "XE1ARS    ";
static const char down_cs[10] = "XE1ARS-R  ";
static const char up_cs[10] = "XE1ARS    ";
static const char rem1_cs[10] = "REM1      ";
static const char rem2_cs[10] = "REM2      ";

#define DGID 42

static ysf_fich fich(unsigned fi, unsigned fn, unsigned dt)
{
    ysf_fich f;
    memset(&f, 0, sizeof f);
    f.fi = (uint8_t)fi;
    f.cs = 0;
    f.cm = YSF_CM_GROUP;
    f.bn = 0;
    f.bt = 0;
    f.fn = (uint8_t)fn;
    f.ft = 0;   /* MMDVM leaves FT 0 on transmit */
    f.dev = 0;  /* Wide */
    f.mr = YSF_MR_DIRECT;
    f.voip = 0;
    f.dt = (uint8_t)dt;
    f.sql = 0;
    f.sc = DGID;
    return f;
}

/* Build a V/D-1 sequence: HC (CSD1 + CSD2) + CC FN0..FN7 + TC. Returns dibits. */
static unsigned build_vd1(void)
{
    uint8_t frame[YSF_FRAME_BYTES], dib[YSF_FRAME_DIBITS], csd1[20], csd2[20], csd3[20], dtdata[20];
    unsigned n = 0;
    memcpy(csd1, dest_cs, 10);
    memcpy(csd1 + 10, src_cs, 10);
    memcpy(csd2, down_cs, 10);
    memcpy(csd2 + 10, up_cs, 10);
    memcpy(csd3, rem1_cs, 10);
    memcpy(csd3 + 10, rem2_cs, 10);
    ysf_fich f = fich(YSF_FI_HEADER, 0, YSF_DT_VD_MODE1);
    ysf_frame_build(&f, csd1, csd2, frame);
    ysf_bytes_to_dibits(frame, YSF_FRAME_BYTES, dib);
    memcpy(txdib + n, dib, YSF_FRAME_DIBITS);
    n += YSF_FRAME_DIBITS;
    for (unsigned fn = 0; fn < 8; fn++) {
        const uint8_t *dch = csd1;
        if (fn == 1) dch = csd2;
        else if (fn == 2) dch = csd3;
        else if (fn >= 3) {
            memcpy(dtdata, "DT0:0123456789ABCDEF", 20);
            dtdata[2] = (uint8_t)('1' + (fn - 3));
            dch = dtdata;
        }
        f = fich(YSF_FI_COMMUNICATION, fn, YSF_DT_VD_MODE1);
        ysf_frame_build(&f, dch, NULL, frame);
        ysf_bytes_to_dibits(frame, YSF_FRAME_BYTES, dib);
        memcpy(txdib + n, dib, YSF_FRAME_DIBITS);
        n += YSF_FRAME_DIBITS;
    }
    f = fich(YSF_FI_TERMINATOR, 0, YSF_DT_VD_MODE1);
    ysf_frame_build(&f, csd1, csd2, frame);
    ysf_bytes_to_dibits(frame, YSF_FRAME_BYTES, dib);
    memcpy(txdib + n, dib, YSF_FRAME_DIBITS);
    n += YSF_FRAME_DIBITS;
    return n;
}

/* Build a DN (V/D-2) sequence: HC (CSD1 + CSD2, two DCH1s, as MMDVM's
 * processHeaderData reads them) + CC FN0..FN5 (one 10-byte DCH2 each: Dest,
 * Src, Down, Up, Rem1+2, Rem3+4) + TC. Returns dibits. */
static unsigned build_dn(void)
{
    uint8_t frame[YSF_FRAME_BYTES], dib[YSF_FRAME_DIBITS], csd1[20], csd2[20], dch2[10];
    unsigned n = 0;
    memcpy(csd1, dest_cs, 10);
    memcpy(csd1 + 10, src_cs, 10);
    memcpy(csd2, down_cs, 10);
    memcpy(csd2 + 10, up_cs, 10);
    ysf_fich f = fich(YSF_FI_HEADER, 0, YSF_DT_VD_MODE2);
    ysf_frame_build(&f, csd1, csd2, frame);
    ysf_bytes_to_dibits(frame, YSF_FRAME_BYTES, dib);
    memcpy(txdib + n, dib, YSF_FRAME_DIBITS);
    n += YSF_FRAME_DIBITS;
    for (unsigned fn = 0; fn < 6; fn++) {
        switch (fn) {
        case 0: memcpy(dch2, dest_cs, 10); break;
        case 1: memcpy(dch2, src_cs, 10); break;
        case 2: memcpy(dch2, down_cs, 10); break;
        case 3: memcpy(dch2, up_cs, 10); break;
        case 4: memcpy(dch2, "REM1 REM2 ", 10); break;   /* Rem1 + Rem2, 5 bytes each */
        default: memcpy(dch2, "REM3 REM4 ", 10); break;
        }
        f = fich(YSF_FI_COMMUNICATION, fn, YSF_DT_VD_MODE2);
        ysf_frame_build(&f, dch2, NULL, frame);
        ysf_bytes_to_dibits(frame, YSF_FRAME_BYTES, dib);
        memcpy(txdib + n, dib, YSF_FRAME_DIBITS);
        n += YSF_FRAME_DIBITS;
    }
    f = fich(YSF_FI_TERMINATOR, 0, YSF_DT_VD_MODE2);
    ysf_frame_build(&f, csd1, csd2, frame);
    ysf_bytes_to_dibits(frame, YSF_FRAME_BYTES, dib);
    memcpy(txdib + n, dib, YSF_FRAME_DIBITS);
    n += YSF_FRAME_DIBITS;
    return n;
}

static ysf_channel_cfg cfg(double cnr, double off, double dev, uint64_t seed)
{
    ysf_channel_cfg c = { cnr, off, dev, 0, 0, 0, 8.0, 0, LEAD_S, seed };
    return c;
}

/* Modulate ndib dibits, run the channel, demodulate, and verify every frame
 * in the sequence. nframes: frames in the sequence. is_dn: DN layout. */
static void run_sequence(const ysf_channel_cfg *c, unsigned ndib, unsigned nframes, bool is_dn, const char *label)
{
    /* A short tail while the PA drops, so the demodulator's filter span
     * covers the last frame's symbols too. */
    for (unsigned i = 0; i < 48; i++) txdib[ndib + i] = (i & 1) ? 3 : 1;
    ndib += 48;
    ysf_mod m;
    ysf_mod_init(&m, TX_GAIN_Q8);
    size_t n8 = 0;
    for (unsigned i = 0; i < ndib; i++) n8 += ysf_mod_dibit(&m, txdib[i], tx8 + n8);
    n8 += ysf_mod_flush(&m, tx8 + n8);
    assert(n8 < MAX_SAMP);
    n8 = ysf_channel_run(c, tx8, n8, TX_GAIN_Q8 / 256.0, rx8);

    ysf_demod d;
    ysf_demod_init(&d);
    size_t lead8 = (size_t)(c->lead_s * 8000), open = lead8 + SQUELCH_MS * 8;
    size_t nd = ysf_demod_samples(&d, rx8, open, rxdib, MAX_DIB);
    ysf_demod_reacquire(&d);
    nd += ysf_demod_samples(&d, rx8 + open, n8 - open, rxdib + nd, MAX_DIB - nd);

    /* First sync: 480 lead dibits + ~24 for the 5 ms squelch delay, ±4 for
     * acquisition wobble. Later syncs exactly one frame (480 dibits) apart. */
    size_t first = ysf_find_sync(rxdib, nd, YSF_SYNC_MAX_ERRORS);
    fprintf(stderr, "%s: first sync at %zu (nd %zu)\n", label, first, nd);
    CHECK(first != SIZE_MAX && first >= 480 - 4 && first <= 480 + 24 + 4);
    if (first == SIZE_MAX) return;
    uint8_t frame[YSF_FRAME_BYTES];
    for (unsigned k = 0; k < nframes; k++) {
        size_t pos = first + (size_t)k * YSF_FRAME_DIBITS;
        if (k > 0) {
            /* The next sync may sit a few dibits either side of the nominal
             * position: search a ±4 dibit window around it. */
            size_t found = ysf_find_sync(rxdib + pos - 4, 28, YSF_SYNC_MAX_ERRORS);
            CHECK(found != SIZE_MAX);
            if (found == SIZE_MAX) continue;
            pos = pos - 4 + found;
        }
        CHECK(pos + YSF_FRAME_DIBITS <= nd);
        if (pos + YSF_FRAME_DIBITS > nd) continue;
        ysf_dibits_to_bytes(rxdib + pos, YSF_FRAME_DIBITS, frame);
        ysf_fich f;
        uint8_t dch[20], dch2[20];
        unsigned dlen = 0;
        bool ok = ysf_frame_decode(frame, &f, dch, dch2, &dlen);
        fprintf(stderr, "%s frame %u: decode %d FI %u DT %u FN %u Dev %u DG %u\n", label, k, ok, f.fi, f.dt, f.fn, f.dev, f.sc);
        if (!ok) {
            /* Where did it break: bit errors per region against the transmitted dibits. */
            unsigned e_sync = 0, e_fich = 0, e_pay = 0;
            for (unsigned i = 0; i < YSF_FRAME_DIBITS; i++) {
                uint8_t x = (uint8_t)(rxdib[pos + i] ^ txdib[(size_t)k * YSF_FRAME_DIBITS + i]);
                unsigned e = (x & 1u) + ((x >> 1) & 1u);
                if (i < 20) e_sync += e;
                else if (i < 120) e_fich += e;
                else e_pay += e;
            }
            fprintf(stderr, "%s frame %u: bit errors sync %u / 40, fich %u / 200, payload %u / 720\n",
                    label, k, e_sync, e_fich, e_pay);
        }
        CHECK(ok);
        if (!ok) continue;
        CHECK(f.dt == (is_dn ? YSF_DT_VD_MODE2 : YSF_DT_VD_MODE1));
        CHECK(f.dev == 0);
        CHECK(f.sc == DGID);
        unsigned expect_fi = k == 0 ? YSF_FI_HEADER : k == nframes - 1 ? YSF_FI_TERMINATOR : YSF_FI_COMMUNICATION;
        CHECK(f.fi == expect_fi);
        if (f.fi == YSF_FI_COMMUNICATION) CHECK(f.fn == k - 1);
        if (!is_dn) {
            CHECK(dlen == 20);
            if (k == 0) {
                CHECK(!memcmp(dch, dest_cs, 10) && !memcmp(dch + 10, src_cs, 10));
                CHECK(!memcmp(dch2, down_cs, 10) && !memcmp(dch2 + 10, up_cs, 10));
            } else if (k == 1) {
                CHECK(!memcmp(dch, dest_cs, 10) && !memcmp(dch + 10, src_cs, 10));
            } else if (k == 2) {
                CHECK(!memcmp(dch, down_cs, 10) && !memcmp(dch + 10, up_cs, 10));
            } else if (k == 3) {
                CHECK(!memcmp(dch, rem1_cs, 10) && !memcmp(dch + 10, rem2_cs, 10));
            } else if (k >= 4 && k <= 8) {
                char expect[20];
                memcpy(expect, "DT0:0123456789ABCDEF", 20);
                expect[2] = (char)('1' + (k - 4));
                CHECK(!memcmp(dch, expect, 20));
            } else if (k == 9) {
                CHECK(!memcmp(dch, dest_cs, 10) && !memcmp(dch + 10, src_cs, 10));
                CHECK(!memcmp(dch2, down_cs, 10) && !memcmp(dch2 + 10, up_cs, 10));
            }
        } else {
            if (k == 0) {
                CHECK(dlen == 20);
                CHECK(!memcmp(dch, dest_cs, 10) && !memcmp(dch + 10, src_cs, 10));
                CHECK(!memcmp(dch2, down_cs, 10) && !memcmp(dch2 + 10, up_cs, 10));
            } else if (k >= 1 && k <= 6) {
                CHECK(dlen == 10);
                const char *expect = NULL;
                switch (k - 1) {
                case 0: expect = dest_cs; break;
                case 1: expect = src_cs; break;
                case 2: expect = down_cs; break;
                case 3: expect = up_cs; break;
                case 4: expect = "REM1 REM2 "; break;
                default: expect = "REM3 REM4 "; break;
                }
                CHECK(!memcmp(dch, expect, 10));
            } else if (k == 7) {
                CHECK(dlen == 20);
                CHECK(!memcmp(dch, dest_cs, 10) && !memcmp(dch + 10, src_cs, 10));
                CHECK(!memcmp(dch2, down_cs, 10) && !memcmp(dch2 + 10, up_cs, 10));
            }
        }
    }
}

int main(void)
{
    /* Whitening: our PN(9,5) generator against MMDVM's fixed table, byte by byte. */
    uint8_t white[20];
    ysf_whitening_generate(white);
    fprintf(stderr, "whitening: %02X %02X %02X %02X ...\n", white[0], white[1], white[2], white[3]);
    CHECK(!memcmp(white, mmdvm_whitening, 20));

    /* Golay spot checks against MMDVM's ENCODING_TABLE_24128 values. */
    CHECK(ysf_golay_encode(0) == 0x000000);
    CHECK(ysf_golay_encode(1) == 0x0018EB);
    CHECK(ysf_golay_encode(2) == 0x00293E);
    CHECK(ysf_golay_encode(0xFFF) == 0xFFFFFF);
    CHECK(ysf_golay_encode(0x555) == 0x555D0D);
    for (unsigned i = 0; i < 64; i++) {
        uint32_t data = (i * 0x41 + 0x123) & 0xFFF;
        uint32_t code = ysf_golay_encode(data), back = 0;
        CHECK(ysf_golay_decode(code, &back) && back == data);
        /* One, two and three bit errors inside the 23-bit part still decode
         * to the same data. (An error in the extension bit 0 on top of errors
         * in the 23-bit part makes MMDVM's validity rule reject the word even
         * though the data bits are right, so the test does not flip bit 0.) */
        uint32_t err1 = code ^ 0x000002u, err2 = code ^ 0x000022u, err3 = code ^ 0x002022u;
        CHECK(ysf_golay_decode(err1, &back) && back == data);
        CHECK(ysf_golay_decode(err2, &back) && back == data);
        CHECK(ysf_golay_decode(err3, &back) && back == data);
    }

    /* FICH byte-level round-trip, all fields incl. the ones MMDVM does not expose. */
    ysf_fich f;
    memset(&f, 0, sizeof f);
    f.fi = 1; f.cs = 2; f.cm = 3; f.bn = 3; f.bt = 2; f.fn = 5; f.ft = 6;
    f.dev = 1; f.mr = 5; f.voip = 1; f.dt = 2; f.sql = 1; f.sc = 127;
    uint8_t fich_air[YSF_FICH_BYTES], fich_air_bad[YSF_FICH_BYTES];
    ysf_fich_encode(&f, fich_air);
    ysf_fich g;
    CHECK(ysf_fich_decode(fich_air, &g));
    CHECK(g.fi == 1 && g.cs == 2 && g.cm == 3 && g.bn == 3 && g.bt == 2 && g.fn == 5 && g.ft == 6);
    CHECK(g.dev == 1 && g.mr == 5 && g.voip == 1 && g.dt == 2 && g.sql == 1 && g.sc == 127);
    /* One flipped bit in the air FICH still decodes (Golay + Viterbi). */
    memcpy(fich_air_bad, fich_air, sizeof fich_air_bad);
    fich_air_bad[10] ^= 0x04;
    CHECK(ysf_fich_decode(fich_air_bad, &g) && g.fn == 5 && g.sc == 127);
    /* Thirty flipped bits do not. */
    memcpy(fich_air_bad, fich_air, sizeof fich_air_bad);
    for (unsigned i = 0; i < 30; i++) fich_air_bad[i / 8] ^= (uint8_t)(0x80u >> (i % 8));
    CHECK(!ysf_fich_decode(fich_air_bad, &g));

    /* DCH byte-level round-trips. */
    uint8_t data20[20], out20[20], air45[45];
    memcpy(data20, dest_cs, 10);
    memcpy(data20 + 10, src_cs, 10);
    ysf_dch1_encode(data20, air45);
    CHECK(ysf_dch1_decode(air45, out20) && !memcmp(out20, data20, 20));
    uint8_t data10[10], out10[10], air25[25];
    memcpy(data10, src_cs, 10);
    ysf_dch2_encode(data10, air25);
    CHECK(ysf_dch2_decode(air25, out10) && !memcmp(out10, data10, 10));
    /* A flipped bit in the air DCH still decodes (Viterbi); a corrupted
     * frame fails the CRC. */
    air45[20] ^= 0x08;
    CHECK(ysf_dch1_decode(air45, out20) && !memcmp(out20, data20, 20));
    memset(air45, 0xFF, sizeof air45);
    CHECK(!ysf_dch1_decode(air45, out20));

    /* Sync search on the transmitted dibits: exact, tolerant, and absent. */
    unsigned ndib = build_vd1();
    CHECK(ndib == 10 * YSF_FRAME_DIBITS);
    CHECK(ysf_find_sync(txdib, ndib, 0) == 0);
    uint8_t dib_bad[MAX_DIB];
    memcpy(dib_bad, txdib, ndib);
    dib_bad[0] ^= 1;   /* one bit wrong in the first sync dibit */
    dib_bad[5] ^= 3;   /* both bits wrong in another */
    CHECK(ysf_find_sync(dib_bad, ndib, 0) == SIZE_MAX || ysf_find_sync(dib_bad, ndib, 0) == YSF_FRAME_DIBITS);
    CHECK(ysf_find_sync(dib_bad, ndib, YSF_SYNC_MAX_ERRORS) == 0);
    /* Whole-frame build/decode without the modem, and sync rejection. */
    uint8_t frame[YSF_FRAME_BYTES];
    ysf_fich hf = fich(YSF_FI_HEADER, 0, YSF_DT_VD_MODE1);
    uint8_t csd1[20], csd2[20];
    memcpy(csd1, dest_cs, 10);
    memcpy(csd1 + 10, src_cs, 10);
    memcpy(csd2, down_cs, 10);
    memcpy(csd2 + 10, up_cs, 10);
    ysf_frame_build(&hf, csd1, csd2, frame);
    ysf_fich df;
    uint8_t ddch[20], ddch2[20];
    unsigned dlen = 0;
    CHECK(ysf_frame_decode(frame, &df, ddch, ddch2, &dlen) && dlen == 20);
    CHECK(df.fi == YSF_FI_HEADER && df.dt == YSF_DT_VD_MODE1 && df.sc == DGID);
    CHECK(!memcmp(ddch, csd1, 20) && !memcmp(ddch2, csd2, 20));
    /* A sync corrupted beyond the 4-bit tolerance is rejected (a 1-bit sync
     * error would still decode: ysf_frame_decode tolerates YSF_SYNC_MAX_ERRORS). */
    frame[0] ^= 0xFF;
    CHECK(!ysf_frame_decode(frame, &df, ddch, ddch2, &dlen));

    /* Modulator into demodulator directly: loopback, then through the FM
     * channel clean and with noise. */
    ysf_channel_cfg c;
    unsigned nd;
    ysf_mod m;
    ysf_demod d;
    /* Loopback (no channel): the first frame's sync is found at once. */
    ysf_mod_init(&m, TX_GAIN_Q8);
    size_t n8 = 0;
    for (unsigned i = 0; i < ndib; i++) n8 += ysf_mod_dibit(&m, txdib[i], tx8 + n8);
    n8 += ysf_mod_flush(&m, tx8 + n8);
    assert(n8 + 1 >= ndib * 5 / 3 && n8 <= ndib * 5 / 3 + 1);   /* 5 samples every 3 symbols */
    ysf_demod_init(&d);
    nd = ysf_demod_samples(&d, tx8, n8, rxdib, MAX_DIB);
    size_t pos = ysf_find_sync(rxdib, nd, YSF_SYNC_MAX_ERRORS);
    fprintf(stderr, "loopback: first sync at %zu (nd %u)\n", pos, nd);
    CHECK(pos != SIZE_MAX && pos <= 8);
    if (pos != SIZE_MAX) {
        ysf_dibits_to_bytes(rxdib + pos, YSF_FRAME_DIBITS, frame);
        CHECK(ysf_frame_decode(frame, &df, ddch, ddch2, &dlen) && dlen == 20);
        CHECK(df.fi == YSF_FI_HEADER && df.sc == DGID);
        CHECK(!memcmp(ddch, csd1, 20) && !memcmp(ddch2, csd2, 20));
    }

    /* Through the FM channel: clean, C/N 20 dB, C/N 10 dB, V/D-1 and DN. */
    c = cfg(300, 0, 1.0, 1);
    run_sequence(&c, build_vd1(), 10, false, "vd1 clean");
    c = cfg(20, 0, 1.0, 2);
    run_sequence(&c, build_vd1(), 10, false, "vd1 C/N 20 dB");
    c = cfg(10, 0, 1.0, 3);
    run_sequence(&c, build_vd1(), 10, false, "vd1 C/N 10 dB");
    c = cfg(300, 0, 1.0, 4);
    run_sequence(&c, build_dn(), 8, true, "dn clean");
    c = cfg(20, 0, 1.0, 5);
    run_sequence(&c, build_dn(), 8, true, "dn C/N 20 dB");
    c = cfg(10, 0, 1.0, 6);
    run_sequence(&c, build_dn(), 8, true, "dn C/N 10 dB");

    fprintf(stderr, "checks %u failures %u\n", checks, failures);
    assert(failures == 0);
    printf("PASS YSF modem: %u checks, modulator/demodulator loopback, V/D-1 and DN through the FM channel "
           "(clean, C/N 20 dB, C/N 10 dB)\n",
           checks);
    return 0;
}
